(3936677, 560264, 72782, '<td valign="top">Nice color, interesting subject,some parts are over exposed, and the focus is not as clear as it could be.</td>', 'Nice color, interesting subject,some parts are over exposed, and the focus is not as clear as it could be.', '2007-07-25 16:52:14.000000', NULL, 1),
(3936679, 559548, 66310, '<td valign="top">cool! Very nice visual and creativity!....8</td>', 'cool! Very nice visual and creativity!....8', '2007-07-25 16:52:25.000000', NULL, 1),
