(3936685, 560528, 66310, '<td valign="top">I like the colors, but it is just a bit too busy for my taste</td>', 'I like the colors, but it is just a bit too busy for my taste', '2007-07-25 16:53:10.000000', NULL, 1),
(3936686, 559201, 66310, '<td valign="top">Good concept and lines, but the picture lacks "punch"</td>', 'Good concept and lines, but the picture lacks "punch"', '2007-07-25 16:53:48.000000', NULL, 1),
(3936689, 560546, 66310, '<td valign="top">Nice richness to this shot......7</td>', 'Nice richness to this shot......7', '2007-07-25 16:54:26.000000', NULL, 1),
(3936693, 557877, 66310, '<td valign="top">While I like the colors and the different perspective, it looks like much of the photo is a bit blurred</td>', 'While I like the colors and the different perspective, it looks like much of the photo is a bit blurred', '2007-07-25 16:55:18.000000', NULL, 1),
(3936696, 559506, 66310, '<td valign="top">Very nice capture</td>', 'Very nice capture', '2007-07-25 16:55:42.000000', NULL, 1),
(3936700, 560288, 66310, '<td valign="top">Nice colors and effect</td>', 'Nice colors and effect', '2007-07-25 16:57:28.000000', NULL, 1),
(3936703, 557152, 66310, '<td valign="top">I like this shot, just think it would be a bit stronger if to the right a bit</td>', 'I like this shot, just think it would be a bit stronger if to the right a bit', '2007-07-25 16:58:12.000000', NULL, 1),
(3936704, 560229, 81082, '<td valign="top">Good arrangement, but the items could have been more striking (e.g., elegant, long-stemmed glasses, a more vibrant rose).</td>', 'Good arrangement, but the items could have been more striking (e.g., elegant, long-stemmed glasses, a more vibrant rose).', '2007-07-25 16:58:34.000000', NULL, 1),
(3936707, 560399, 81082, '<td valign="top">I like the great colors you used, but this photo seems to be trying too hard - there are almost too many items, and they''re arranged just so, so that they seem like an arranged array, and rather than being organized or scattered, they seem to be somewhere in the middle, which is less powerful than the extremes.</td>', 'I like the great colors you used, but this photo seems to be trying too hard - there are almost too many items, and they''re arranged just so, so that they seem like an arranged array, and rather than being organized or scattered, they seem to be somewhere in the middle, which is less powerful than the extremes.', '2007-07-25 17:01:17.000000', NULL, 1),
(3936709, 560526, 81082, '<td valign="top">Love the sky''s hue that you captured.</td>', 'Love the sky''s hue that you captured.', '2007-07-25 17:01:58.000000', NULL, 1),
(3936720, 560093, 66310, '<td valign="top">Strong shot!! I hope you market this print, and the B/W really works!!! For your excellent vision and creativity...........8</td>', 'Strong shot!! I hope you market this print, and the B/W really works!!! For your excellent vision and creativity...........8', '2007-07-25 17:04:51.000000', NULL, 1),
(3936726, 559465, 66310, '<td valign="top">Nice macro capture!</td>', 'Nice macro capture!', '2007-07-25 17:05:26.000000', NULL, 1),
(3936729, 559733, 66310, '<td valign="top">while this shot doesn''t really work for me (which is ok, because I am sure some people love it....that is why we are different), I''m giving you a 6 for creativity and vision.</td>', 'while this shot doesn''t really work for me (which is ok, because I am sure some people love it....that is why we are different), I''m giving you a 6 for creativity and vision.', '2007-07-25 17:06:42.000000', NULL, 1),
(3936740, 559289, 66310, '<td valign="top">I''m not doing it</td>', 'I''m not doing it', '2007-07-25 17:08:40.000000', NULL, 1),
(3936742, 559548, 70000, '<td valign="top">OOHH!!! how unexpected and creative!! this is simply lovely, this would have been great for the paper challenge as well. great shot</td>', 'OOHH!!! how unexpected and creative!! this is simply lovely, this would have been great for the paper challenge as well. great shot', '2007-07-25 17:09:04.000000', NULL, 1),
(3936744, 560298, 70000, '<td valign="top">lighting seems a bit harsh with dark shaddows i guess from the flash? makes the photo less appealing in my opnion</td>', 'lighting seems a bit harsh with dark shaddows i guess from the flash? makes the photo less appealing in my opnion', '2007-07-25 17:09:54.000000', NULL, 1),
