(3937921, 558958, 70852, '<td valign="top">White balance needs correcting I think.</td>', 'White balance needs correcting I think.', '2007-07-25 23:13:57.000000', NULL, 1),
(3937924, 560197, 77724, '<td valign="top">lol.  You''re probably gonna get hammered by those without a sense of humor.</td>', 'lol.  You''re probably gonna get hammered by those without a sense of humor.', '2007-07-25 23:14:54.000000', NULL, 1),
(3937926, 559515, 77724, '<td valign="top">Nice composition, good contrast, not bothered by blown highlights - I think they work here.  Well done.</td>', 'Nice composition, good contrast, not bothered by blown highlights - I think they work here.  Well done.', '2007-07-25 23:16:39.000000', NULL, 1),
(3937929, 558821, 77724, '<td valign="top">Nice classic look.</td>', 'Nice classic look.', '2007-07-25 23:17:15.000000', NULL, 1),
(3937932, 559620, 77724, '<td valign="top">Simple in a good way.  nice lines, colors and textures.</td>', 'Simple in a good way.  nice lines, colors and textures.', '2007-07-25 23:18:30.000000', NULL, 1),
(3938059, 558059, 70852, '<td valign="top">I would have voted higher if the colors weren''t so pale, and the focus on the tomato was better.</td>', 'I would have voted higher if the colors weren''t so pale, and the focus on the tomato was better.', '2007-07-25 23:58:37.000000', NULL, 1),
(3938083, 559893, 70852, '<td valign="top">Seems that resizing distorted this otherwise nice picture. The backs of the chairs have jagged edges.</td>', 'Seems that resizing distorted this otherwise nice picture. The backs of the chairs have jagged edges.', '2007-07-26 00:08:33.000000', NULL, 1),
(3938088, 559321, 70852, '<td valign="top">White balance seems a bit off?</td>', 'White balance seems a bit off?', '2007-07-26 00:09:01.000000', NULL, 1),
(3938123, 560459, 70000, '<td valign="top">this is a very happy picture, nice colors, brought a smile to my face</td>', 'this is a very happy picture, nice colors, brought a smile to my face', '2007-07-26 00:17:11.000000', NULL, 1),
(3938131, 560549, 60495, '<td valign="top">I like the flower it really has cool shapes but I am not surethe background does it justice, it just seems a little distracting.</td>', 'I like the flower it really has cool shapes but I am not surethe background does it justice, it just seems a little distracting.', '2007-07-26 00:19:31.000000', NULL, 1),
(3938144, 560211, 60495, '<td valign="top">Nothing like a good cigar after a meal like that....</td>', 'Nothing like a good cigar after a meal like that....', '2007-07-26 00:22:33.000000', NULL, 1),
(3938258, 558959, 93927, '<td valign="top">this has blue written all over it! i love it. the lighting is amazing, great job!</td>', 'this has blue written all over it! i love it. the lighting is amazing, great job!', '2007-07-26 00:55:42.000000', NULL, 1),
(3938288, 559976, 66310, '<td valign="top">Excellent colors</td>', 'Excellent colors', '2007-07-26 01:07:25.000000', NULL, 1),
(3938294, 560052, 66310, '<td valign="top">too cluttered</td>', 'too cluttered', '2007-07-26 01:08:23.000000', NULL, 1),
(3938301, 560532, 66310, '<td valign="top">I like. the monochrome really adds to the mood and atmosphere....6</td>', 'I like. the monochrome really adds to the mood and atmosphere....6', '2007-07-26 01:10:33.000000', NULL, 1),
(3938311, 559321, 80200, '<td valign="top">The photo is very yellowish.</td>', 'The photo is very yellowish.', '2007-07-26 01:13:00.000000', NULL, 1),
(3938348, 558281, 81362, '<td valign="top">Looks like a portrait to me. The definitions of "still life" consistently call for an image of inanimate objects, so this picture doesn''t seem to meet the challenge, even if he is standing still.</td>', 'Looks like a portrait to me. The definitions of "still life" consistently call for an image of inanimate objects, so this picture doesn''t seem to meet the challenge, even if he is standing still.', '2007-07-26 01:22:40.000000', NULL, 1),
(3938354, 559893, 81642, '<td valign="top">don''t you think the image is a little washed out or over exposed ?</td>', 'don''t you think the image is a little washed out or over exposed ?', '2007-07-26 01:28:46.000000', NULL, 1),
(3938369, 559112, 15511, '<td valign="top">At first, I thought the image is too cluttered, yet everything is clear &amp; sharp. There''s a lot to look at here; and that makes it worth looking at longer. My only suggestion is that a bit more negative space would help frame your subject.</td>', 'At first, I thought the image is too cluttered, yet everything is clear & sharp. There''s a lot to look at here; and that makes it worth looking at longer. My only suggestion is that a bit more negative space would help frame your subject.', '2007-07-26 01:35:24.000000', NULL, 1),
(3938378, 557877, 15511, '<td valign="top">Image needs more negative space. The whiter light from the left seems out of place here. Nice collection.</td>', 'Image needs more negative space. The whiter light from the left seems out of place here. Nice collection.', '2007-07-26 01:43:27.000000', NULL, 1),
(3938385, 559112, 81362, '<td valign="top">The rich variety of colorful flowes and fruits makes me want to view this image over and over. Nicely done.</td>', 'The rich variety of colorful flowes and fruits makes me want to view this image over and over. Nicely done.', '2007-07-26 01:47:02.000000', NULL, 1),
(3938410, 559314, 48058, '<td valign="top">To me, this doesn''t relate to still life.</td>', 'To me, this doesn''t relate to still life.', '2007-07-26 01:58:23.000000', NULL, 1),
(3938411, 558729, 48058, '<td valign="top">To me, this just does not relate to the idea of still life.</td>', 'To me, this just does not relate to the idea of still life.', '2007-07-26 01:59:00.000000', NULL, 1),
(3938417, 559989, 48058, '<td valign="top">This would have been worth at least an 8 to me had you not cut off the glass. Since you have it in a horizontal orientation, it would have helped had you laid the glass down behind the fruit.</td>', 'This would have been worth at least an 8 to me had you not cut off the glass. Since you have it in a horizontal orientation, it would have helped had you laid the glass down behind the fruit.', '2007-07-26 02:00:47.000000', NULL, 1),
(3938423, 560061, 48058, '<td valign="top">I would have gone to an 8 but the image just seems to squeezed in on the sides and the leaves on the right lead my eyes right off the page.</td>', 'I would have gone to an 8 but the image just seems to squeezed in on the sides and the leaves on the right lead my eyes right off the page.', '2007-07-26 02:01:48.000000', NULL, 1),
(3938455, 560460, 80200, '<td valign="top">Nice photo</td>', 'Nice photo', '2007-07-26 02:15:01.000000', NULL, 1),
(3938459, 559693, 48058, '<td valign="top">I can''t put my finger on why I can''t give this a 10, but I think it''s the gray background and shadows.  It''s like you were going for a high key picture but didn''t have the lighting to pull it off. So I just couldn''t squeeze out the 10 for you. It was close though.</td>', 'I can''t put my finger on why I can''t give this a 10, but I think it''s the gray background and shadows.  It''s like you were going for a high key picture but didn''t have the lighting to pull it off. So I just couldn''t squeeze out the 10 for you. It was close though.', '2007-07-26 02:17:03.000000', NULL, 1),
(3938462, 559112, 48058, '<td valign="top">I would have given this a higher score except you have the image too squeezed in and you have to much stuff that are unrelated. It''s like you threw in whatever you had handy. Sometimes less is better. But you have good color, good focus and good lighting.</td>', 'I would have given this a higher score except you have the image too squeezed in and you have to much stuff that are unrelated. It''s like you threw in whatever you had handy. Sometimes less is better. But you have good color, good focus and good lighting.', '2007-07-26 02:19:09.000000', NULL, 1),
(3938465, 560490, 48058, '<td valign="top">I liked the color of your flowers, but I couldn''t go higher on the score. It''s the perspective that throws it off for me as well as the out of focus but still visible base of the vase.</td>', 'I liked the color of your flowers, but I couldn''t go higher on the score. It''s the perspective that throws it off for me as well as the out of focus but still visible base of the vase.', '2007-07-26 02:20:35.000000', NULL, 1),
(3938467, 559969, 48058, '<td valign="top">This really needed a bit more light on the shell itself. To me it''s just too much in shadow.</td>', 'This really needed a bit more light on the shell itself. To me it''s just too much in shadow.', '2007-07-26 02:21:17.000000', NULL, 1),
(3938471, 559666, 48058, '<td valign="top">This picture was almost pretty good. The problem to me is that it appears you are shooting from the side rather than square on. That might appear that way because of the fold of the background on the left side. But it throws the balance off in the picture.</td>', 'This picture was almost pretty good. The problem to me is that it appears you are shooting from the side rather than square on. That might appear that way because of the fold of the background on the left side. But it throws the balance off in the picture.', '2007-07-26 02:23:39.000000', NULL, 1),
(3938476, 560046, 48058, '<td valign="top">You could have had a very good picture here, but you have too much seperation between the drink and the peanuts. It''s like there is two seperate pictures going on here. I think it would have had a lot more impact had you put the bowl right next to the glass and maybe had the lose peanuts around the base of the glass. This would have given a connection between the two objects. I think it''s croped a bit tight on the left side as well.  <br/> <br/>Lighting is good as is color and focus. I could have gone a 9 or even a 10 had it been placed just a little bit better.</td>', 'You could have had a very good picture here, but you have too much seperation between the drink and the peanuts. It''s like there is two seperate pictures going on here. I think it would have had a lot more impact had you put the bowl right next to the glass and maybe had the lose peanuts around the base of the glass. This would have given a connection between the two objects. I think it''s croped a bit tight on the left side as well.   Lighting is good as is color and focus. I could have gone a 9 or even a 10 had it been placed just a little bit better.', '2007-07-26 02:27:17.000000', NULL, 1),
(3938480, 560315, 48058, '<td valign="top">This was almost a very good image.  I think it needs a bit more light on the forground objects and the background bottle. If you could have placed a slit light on the bottole and a tad more light on the fruit, I could have gone a 9 or even a 10 on it.</td>', 'This was almost a very good image.  I think it needs a bit more light on the forground objects and the background bottle. If you could have placed a slit light on the bottole and a tad more light on the fruit, I could have gone a 9 or even a 10 on it.', '2007-07-26 02:28:56.000000', NULL, 1),
(3938482, 557448, 48058, '<td valign="top">This really needs some light on the flowers. You have good light on the vase, but the flowers are too much in the dark. A little selective lighting on the flowers and I think it would have really improved this image.</td>', 'This really needs some light on the flowers. You have good light on the vase, but the flowers are too much in the dark. A little selective lighting on the flowers and I think it would have really improved this image.', '2007-07-26 02:30:21.000000', NULL, 1),
(3938484, 558523, 80200, '<td valign="top">Nice title! :)</td>', 'Nice title! :)', '2007-07-26 02:31:09.000000', NULL, 1),
(3938486, 557590, 48058, '<td valign="top">Good idea and nice use of lines and shapes. But to me it''s cropped way too tight and the orange and green colors are out of place in the image. Still, not bad, but it could have been better.</td>', 'Good idea and nice use of lines and shapes. But to me it''s cropped way too tight and the orange and green colors are out of place in the image. Still, not bad, but it could have been better.', '2007-07-26 02:31:27.000000', NULL, 1),
(3938497, 559784, 80200, '<td valign="top">Nice composition and colors, but, ¿and the life?</td>', 'Nice composition and colors, but, ¿and the life?', '2007-07-26 02:37:10.000000', NULL, 1),
(3938498, 559792, 80200, '<td valign="top">Nice shot!</td>', 'Nice shot!', '2007-07-26 02:37:14.000000', NULL, 1),
(3938499, 559749, 80200, '<td valign="top">Your photo is a bit dark, but I like it.</td>', 'Your photo is a bit dark, but I like it.', '2007-07-26 02:37:28.000000', NULL, 1),
(3938500, 559620, 80200, '<td valign="top">Nice shot. For my own taste, it lacks a bit of brightness.</td>', 'Nice shot. For my own taste, it lacks a bit of brightness.', '2007-07-26 02:37:46.000000', NULL, 1),
(3938501, 560492, 24991, '<td valign="top">Horrible compression.</td>', 'Horrible compression.', '2007-07-26 02:37:55.000000', NULL, 1),
(3938502, 558760, 80200, '<td valign="top">Nice place. I would like to see the full trees.</td>', 'Nice place. I would like to see the full trees.', '2007-07-26 02:38:09.000000', NULL, 1),
(3938503, 560090, 80200, '<td valign="top">Nice shot. I''d like to see it cropped in a 3:2 proportion.</td>', 'Nice shot. I''d like to see it cropped in a 3:2 proportion.', '2007-07-26 02:38:37.000000', NULL, 1);
