(3938644, 559961, 68467, '<td valign="top">The WB seems a bit off but nice capture though</td>', 'The WB seems a bit off but nice capture though', '2007-07-26 05:44:12.000000', NULL, 1),
(3938645, 560123, 68467, '<td valign="top">nice sharpness and details</td>', 'nice sharpness and details', '2007-07-26 05:44:53.000000', NULL, 1),
(3938646, 559723, 68467, '<td valign="top">very poor image quality</td>', 'very poor image quality', '2007-07-26 05:45:57.000000', NULL, 1),
(3938648, 560365, 68467, '<td valign="top">the light seems a bit hard, great capture though</td>', 'the light seems a bit hard, great capture though', '2007-07-26 05:47:03.000000', NULL, 1),
(3938649, 559156, 49109, '<td valign="top">not a still life IMHO. a closer crop, better focus and a shallow DOF might have changed that impression</td>', 'not a still life IMHO. a closer crop, better focus and a shallow DOF might have changed that impression', '2007-07-26 05:47:05.000000', NULL, 1),
(3938650, 558029, 49109, '<td valign="top">not a still life. out of focus. very strange aspect ratio. lacks of composition.</td>', 'not a still life. out of focus. very strange aspect ratio. lacks of composition.', '2007-07-26 05:47:09.000000', NULL, 1),
(3938651, 557278, 68467, '<td valign="top">Nice apple, I don´t like the red border though</td>', 'Nice apple, I don´t like the red border though', '2007-07-26 05:48:01.000000', NULL, 1),
(3938652, 559314, 49109, '<td valign="top">definitely not a still life. besides that, I find the space left of the couple too large, had cropped somehwere near the pole</td>', 'definitely not a still life. besides that, I find the space left of the couple too large, had cropped somehwere near the pole', '2007-07-26 05:48:19.000000', NULL, 1),
(3938653, 558203, 49109, '<td valign="top">not a still life. tilted to the right. wrongly exposed, distracting lens flare.</td>', 'not a still life. tilted to the right. wrongly exposed, distracting lens flare.', '2007-07-26 05:48:22.000000', NULL, 1),
(3938654, 558584, 49109, '<td valign="top">cute idea, but IMO not a still life: your main subject is the smoke (transporting the boat);  smoke exists only through being never still and cannot be arranged.</td>', 'cute idea, but IMO not a still life: your main subject is the smoke (transporting the boat);  smoke exists only through being never still and cannot be arranged.', '2007-07-26 05:48:25.000000', NULL, 1),
(3938655, 559548, 68467, '<td valign="top">Very creative and well done</td>', 'Very creative and well done', '2007-07-26 05:48:40.000000', NULL, 1),
(3938656, 560399, 68467, '<td valign="top">I like these colors and the softness of the image</td>', 'I like these colors and the softness of the image', '2007-07-26 05:49:30.000000', NULL, 1),
(3938657, 559002, 49109, '<td valign="top">not moving, still not a still life (i.e. an arrangement of things). besides that, you should have put at least some effort in the lighting</td>', 'not moving, still not a still life (i.e. an arrangement of things). besides that, you should have put at least some effort in the lighting', '2007-07-26 05:49:54.000000', NULL, 1),
(3938658, 560413, 49109, '<td valign="top">not a still life, but a found subject. not very attractive, too</td>', 'not a still life, but a found subject. not very attractive, too', '2007-07-26 05:50:42.000000', NULL, 1),
(3938659, 559599, 68467, '<td valign="top">Nice composition but there are too many things</td>', 'Nice composition but there are too many things', '2007-07-26 05:50:46.000000', NULL, 1),
(3938661, 560539, 49109, '<td valign="top">not a still life. as an architectural shot, it could have been better if there was more of the street included</td>', 'not a still life. as an architectural shot, it could have been better if there was more of the street included', '2007-07-26 05:51:40.000000', NULL, 1),
(3938662, 558447, 68467, '<td valign="top">nice and sharp, but I´m not sure I like the tone</td>', 'nice and sharp, but I´m not sure I like the tone', '2007-07-26 05:52:04.000000', NULL, 1),
(3938664, 558640, 68467, '<td valign="top">nice capture but the composition is a bit too centred for my taste</td>', 'nice capture but the composition is a bit too centred for my taste', '2007-07-26 05:52:49.000000', NULL, 1),
(3938666, 560199, 68467, '<td valign="top">Would have been a nice photo without the locks</td>', 'Would have been a nice photo without the locks', '2007-07-26 05:53:58.000000', NULL, 1),
(3938667, 559976, 68467, '<td valign="top">Great composition and colors one of my top picks</td>', 'Great composition and colors one of my top picks', '2007-07-26 05:54:42.000000', NULL, 1),
(3938668, 558824, 49109, '<td valign="top">not a still life (i.e. a shot of motionless things), but a high-speed shot of a moving subject. lighting is too frontal and created distracting highlights and a flat looking surface. oversharpening created a halo around the orange slice and a  n unsmooth gradient in the background. border is overdone IMO</td>', 'not a still life (i.e. a shot of motionless things), but a high-speed shot of a moving subject. lighting is too frontal and created distracting highlights and a flat looking surface. oversharpening created a halo around the orange slice and a  n unsmooth gradient in the background. border is overdone IMO', '2007-07-26 05:55:04.000000', NULL, 1),
(3938669, 557294, 68467, '<td valign="top">I like this but I think it´s a bit too centred</td>', 'I like this but I think it´s a bit too centred', '2007-07-26 05:55:20.000000', NULL, 1),
(3938671, 558824, 68467, '<td valign="top">Great capture and composition</td>', 'Great capture and composition', '2007-07-26 05:56:27.000000', NULL, 1),
(3938672, 558281, 49109, '<td valign="top">a still life should neither contain people nor landscape, nor architecture (except from architectural details). Besides that, the lights are blown.</td>', 'a still life should neither contain people nor landscape, nor architecture (except from architectural details). Besides that, the lights are blown.', '2007-07-26 05:56:30.000000', NULL, 1),
(3938673, 557118, 49109, '<td valign="top">not a still life, but a shot of a found scenery. lacks of composition, lights are blown</td>', 'not a still life, but a shot of a found scenery. lacks of composition, lights are blown', '2007-07-26 05:57:31.000000', NULL, 1),
(3938674, 558584, 68467, '<td valign="top">This is a fantastic idea and you pull it of very well</td>', 'This is a fantastic idea and you pull it of very well', '2007-07-26 05:57:36.000000', NULL, 1),
(3938675, 559465, 49109, '<td valign="top">would call this a close-up or macro, not a still life - usually an arrangement of things</td>', 'would call this a close-up or macro, not a still life - usually an arrangement of things', '2007-07-26 05:57:37.000000', NULL, 1),
(3938677, 560315, 68467, '<td valign="top">I like the tone of this</td>', 'I like the tone of this', '2007-07-26 05:59:05.000000', NULL, 1),
(3938678, 557809, 49109, '<td valign="top">this is not a still life (i.e. an arrangement of things), but a shot of a found scenery. as that, not very interesting nor of  artistic merits</td>', 'this is not a still life (i.e. an arrangement of things), but a shot of a found scenery. as that, not very interesting nor of  artistic merits', '2007-07-26 05:59:35.000000', NULL, 1),
(3938679, 558959, 68467, '<td valign="top">Stunning capture. I really like the tone of this</td>', 'Stunning capture. I really like the tone of this', '2007-07-26 05:59:47.000000', NULL, 1),
(3938680, 558821, 68467, '<td valign="top">Great capture</td>', 'Great capture', '2007-07-26 06:00:28.000000', NULL, 1),
