(3939593, 559892, 74605, '<td valign="top">Pretty!</td>', 'Pretty!', '2007-07-26 13:30:24.000000', NULL, 1),
(3939596, 560267, 74605, '<td valign="top">Fun idea.  The colors are great!</td>', 'Fun idea.  The colors are great!', '2007-07-26 13:30:46.000000', NULL, 1),
(3939604, 560397, 74605, '<td valign="top">Nice arrangement.  The colors are great.  The door adds a nice dimension and the flowers in the background seen through the glass are great.  One of my favorites.  Voted 10.</td>', 'Nice arrangement.  The colors are great.  The door adds a nice dimension and the flowers in the background seen through the glass are great.  One of my favorites.  Voted 10.', '2007-07-26 13:33:03.000000', NULL, 1),
(3939606, 560090, 74605, '<td valign="top">Nice simplicity.</td>', 'Nice simplicity.', '2007-07-26 13:33:57.000000', NULL, 1),
