(3940920, 558584, 58691, '<td valign="top">Nice shot, although I am not sure that this fits "Still Life". I think this shot represents "movement" on two levels.</td>', 'Nice shot, although I am not sure that this fits "Still Life". I think this shot represents "movement" on two levels.', '2007-07-26 20:59:36.000000', NULL, 1),
(3940923, 559548, 58691, '<td valign="top">While technically a "Still Life", your composition suggests movement, which I think is counter to the challenge. Neat shot, though.</td>', 'While technically a "Still Life", your composition suggests movement, which I think is counter to the challenge. Neat shot, though.', '2007-07-26 21:01:25.000000', NULL, 1),
(3940926, 559693, 58691, '<td valign="top">Creative composition. I think this would be better in color or a certain tint. Plus it could use a bit more contrast.</td>', 'Creative composition. I think this would be better in color or a certain tint. Plus it could use a bit more contrast.', '2007-07-26 21:03:02.000000', NULL, 1),
(3940928, 559120, 58691, '<td valign="top">I like this, although it is a bit chaotic. I don''t think it would be so if you shot it a straight on.</td>', 'I like this, although it is a bit chaotic. I don''t think it would be so if you shot it a straight on.', '2007-07-26 21:05:16.000000', NULL, 1),
(3940935, 558090, 58691, '<td valign="top">I like the way you lit this. Nice job.</td>', 'I like the way you lit this. Nice job.', '2007-07-26 21:06:43.000000', NULL, 1),
(3940940, 559910, 58691, '<td valign="top">Excellent shot. I really like the composition.</td>', 'Excellent shot. I really like the composition.', '2007-07-26 21:08:52.000000', NULL, 1),
(3940941, 557294, 77724, '<td valign="top">cute idea and simple set - nice light and spot on focus earn this high marks.</td>', 'cute idea and simple set - nice light and spot on focus earn this high marks.', '2007-07-26 21:09:07.000000', NULL, 1),
(3940946, 560079, 58691, '<td valign="top">Nice color. The white background is a bit harsh. A neutral or contrasting background would make it pop out even more.</td>', 'Nice color. The white background is a bit harsh. A neutral or contrasting background would make it pop out even more.', '2007-07-26 21:10:41.000000', NULL, 1),
(3940951, 559433, 58691, '<td valign="top">Outstanding lighting. The horizontal line in the front is a bit distracting, but doesn''t interfere with the overall composition.</td>', 'Outstanding lighting. The horizontal line in the front is a bit distracting, but doesn''t interfere with the overall composition.', '2007-07-26 21:13:14.000000', NULL, 1),
(3940953, 560117, 77724, '<td valign="top">nice lines - good exposure</td>', 'nice lines - good exposure', '2007-07-26 21:13:30.000000', NULL, 1),
(3940958, 559046, 58691, '<td valign="top">The highlights are blown out. i think the flowers in the background are too distracting. I think the items in the bowl really call for an inside setting.</td>', 'The highlights are blown out. i think the flowers in the background are too distracting. I think the items in the bowl really call for an inside setting.', '2007-07-26 21:15:50.000000', NULL, 1),
(3940960, 558823, 58691, '<td valign="top">Great composition and alignment.</td>', 'Great composition and alignment.', '2007-07-26 21:17:39.000000', NULL, 1),
(3940964, 560438, 58691, '<td valign="top">Nice job. Great use of color and good composition.</td>', 'Nice job. Great use of color and good composition.', '2007-07-26 21:18:27.000000', NULL, 1),
(3940967, 557471, 77724, '<td valign="top">Awsome - 10</td>', 'Awsome - 10', '2007-07-26 21:19:09.000000', NULL, 1),
(3940968, 560420, 77724, '<td valign="top">nice classic look and feel</td>', 'nice classic look and feel', '2007-07-26 21:20:04.000000', NULL, 1),
(3940971, 560493, 58691, '<td valign="top">I like the arrangement, but I''m not sure if the macro setting was the best for this shot.</td>', 'I like the arrangement, but I''m not sure if the macro setting was the best for this shot.', '2007-07-26 21:21:02.000000', NULL, 1),
(3940973, 560296, 58691, '<td valign="top">Outstanding!Great lighting and textures.</td>', 'Outstanding!Great lighting and textures.', '2007-07-26 21:21:41.000000', NULL, 1),
(3940981, 560256, 58691, '<td valign="top">I like your balance in this photo. Would like to see the red a brighter... but heck, this is a Basic challenge.</td>', 'I like your balance in this photo. Would like to see the red a brighter... but heck, this is a Basic challenge.', '2007-07-26 21:24:23.000000', NULL, 1),
(3940985, 560492, 58691, '<td valign="top">It appears that the image has become skewed in post-production.</td>', 'It appears that the image has become skewed in post-production.', '2007-07-26 21:27:12.000000', NULL, 1),
(3940987, 559746, 58691, '<td valign="top">While the subject is "still", the overall image suggests great movement.</td>', 'While the subject is "still", the overall image suggests great movement.', '2007-07-26 21:28:28.000000', NULL, 1),
(3940990, 558760, 58691, '<td valign="top">moving clouds and rippling water don''t give me the feeling of a "Still Life" image.</td>', 'moving clouds and rippling water don''t give me the feeling of a "Still Life" image.', '2007-07-26 21:29:52.000000', NULL, 1),
(3940994, 560428, 58691, '<td valign="top">Nice composition. I love how the softness of the cream colored items contrast with the texture and sharpness of the brown vase and the pine cones. The lighting rocks as well.</td>', 'Nice composition. I love how the softness of the cream colored items contrast with the texture and sharpness of the brown vase and the pine cones. The lighting rocks as well.', '2007-07-26 21:32:09.000000', NULL, 1),
(3940998, 559515, 58691, '<td valign="top">While technically a "Still Life", the overall image suggests or alludes to movement. Good composition and lighting.</td>', 'While technically a "Still Life", the overall image suggests or alludes to movement. Good composition and lighting.', '2007-07-26 21:34:52.000000', NULL, 1),
(3941002, 557448, 58691, '<td valign="top">I like the back lighting, but this would be better if you lit the front of the flowers a bit as well.</td>', 'I like the back lighting, but this would be better if you lit the front of the flowers a bit as well.', '2007-07-26 21:36:12.000000', NULL, 1),
(3941004, 557406, 58691, '<td valign="top">This appears to be a bit out of focus.</td>', 'This appears to be a bit out of focus.', '2007-07-26 21:37:33.000000', NULL, 1),
(3941009, 560524, 58691, '<td valign="top">Nice shot. I would''ve rated it higher had you either cropped a bit closer or zoomed back and not chopped off the box.</td>', 'Nice shot. I would''ve rated it higher had you either cropped a bit closer or zoomed back and not chopped off the box.', '2007-07-26 21:39:05.000000', NULL, 1),
(3941010, 559784, 58691, '<td valign="top">Color, composition and lighting all done very well. Good shot.</td>', 'Color, composition and lighting all done very well. Good shot.', '2007-07-26 21:40:31.000000', NULL, 1),
(3941017, 559893, 58691, '<td valign="top">It appears that this image was distorted in post-production - look at the lines on the chaise lounges. The waving flag negates the stillness off the image.</td>', 'It appears that this image was distorted in post-production - look at the lines on the chaise lounges. The waving flag negates the stillness off the image.', '2007-07-26 21:43:43.000000', NULL, 1),
(3941026, 559733, 58691, '<td valign="top">I''d really like this if the person were not in the image. The fact that he/she is out of focus suggests a certain movement.</td>', 'I''d really like this if the person were not in the image. The fact that he/she is out of focus suggests a certain movement.', '2007-07-26 21:46:34.000000', NULL, 1),
(3941033, 559749, 58691, '<td valign="top">Adjust the curves on this and the yellow would really pop.</td>', 'Adjust the curves on this and the yellow would really pop.', '2007-07-26 21:48:47.000000', NULL, 1),
(3941038, 560405, 58691, '<td valign="top">Wow, these are really unique colors. Good composition as well.</td>', 'Wow, these are really unique colors. Good composition as well.', '2007-07-26 21:50:11.000000', NULL, 1),
(3941051, 558281, 58691, '<td valign="top">I see this as a portrait instead of a traditional "Still Life" - not necessarily mutually exclusive. The lighting is a bit off as his shirt is blown out.</td>', 'I see this as a portrait instead of a traditional "Still Life" - not necessarily mutually exclusive. The lighting is a bit off as his shirt is blown out.', '2007-07-26 21:54:39.000000', NULL, 1);
