(3943461, 558356, 77724, '<td valign="top">Nice tones and textures - comfortable homey feel too.  Well done.</td>', 'Nice tones and textures - comfortable homey feel too.  Well done.', '2007-07-27 19:10:13.000000', NULL, 1),
(3943463, 559548, 61651, '<td valign="top">Marvelous idea and execution.  To take that conceptual leap from presenting a paper swan on "water" of any sort, to a sea of musical notes that illustrates the word play with swan on a lake/Swan Lake is admirable. Edges of the swan against the black look slightly jaggy on my monitor - don''t know if it''s down to lighting or sharpening.  Nevertheless this shot rates a 10 from me.</td>', 'Marvelous idea and execution.  To take that conceptual leap from presenting a paper swan on "water" of any sort, to a sea of musical notes that illustrates the word play with swan on a lake/Swan Lake is admirable. Edges of the swan against the black look slightly jaggy on my monitor - don''t know if it''s down to lighting or sharpening.  Nevertheless this shot rates a 10 from me.', '2007-07-27 19:10:25.000000', NULL, 1),
(3943467, 560288, 61651, '<td valign="top">Very crisp and nice tones - wonder if it''s the same person who did the Science entry? :)  Nicely executed all the same - 9.</td>', 'Very crisp and nice tones - wonder if it''s the same person who did the Science entry? :)  Nicely executed all the same - 9.', '2007-07-27 19:11:49.000000', NULL, 1),
(3943472, 557877, 77724, '<td valign="top">Nice arrangement and pretty good light.  Might be mor interesting if not so straight on.</td>', 'Nice arrangement and pretty good light.  Might be mor interesting if not so straight on.', '2007-07-27 19:12:52.000000', NULL, 1),
(3943473, 560343, 61651, '<td valign="top">I like how you used depth of field here to present a still life that blends into an abstract.  Very nice.</td>', 'I like how you used depth of field here to present a still life that blends into an abstract.  Very nice.', '2007-07-27 19:12:56.000000', NULL, 1),
(3943494, 559586, 77724, '<td valign="top">Too much going on here.  Needs a clear subject.</td>', 'Too much going on here.  Needs a clear subject.', '2007-07-27 19:20:04.000000', NULL, 1),
