INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4358005, 558821, 87093, '<td valign="top">This one sure should have been rated higher, well done!</td>', 'This one sure should have been rated higher, well done!', '2008-01-03 16:22:32.000000', NULL, 0),
(4376881, 557785, 48228, '<td valign="top">I love the freshnes of this fine floral image, and also the wonderful soft rich pastle colors..... <br/> <br/>Definately my kind of image.....</td>', 'I love the freshnes of this fine floral image, and also the wonderful soft rich pastle colors.....  Definately my kind of image.....', '2008-01-09 08:13:22.000000', NULL, 0),
(4379684, 558821, 67697, '<td valign="top">Oooh I did not vote in this challenge so I did not see this.  It''s gorgeous.  I love the lighting and the colors of the fruit are so beautiful!  What a wonderful picture!</td>', 'Oooh I did not vote in this challenge so I did not see this.  It''s gorgeous.  I love the lighting and the colors of the fruit are so beautiful!  What a wonderful picture!', '2008-01-09 22:21:31.000000', NULL, 0),
(4388551, 557414, 47483, '<td valign="top">A good composition, but the border is bit distracting.</td>', 'A good composition, but the border is bit distracting.', '2008-01-13 05:08:15.000000', NULL, 0),
(4406474, 559548, 73981, '<td valign="top">I would have to say that what makes this picture so great is it''s simplicity. Sometimes people OVER think their ideas, but this one comes out simple but just nails the challenge. I should''ve been thinking origami, since I live in Japan...but alas, I didn''t. I have however tried to duplicate the shot with little success. I need to work on my lighting. You have it down pat!! Love it!!</td>', 'I would have to say that what makes this picture so great is it''s simplicity. Sometimes people OVER think their ideas, but this one comes out simple but just nails the challenge. I should''ve been thinking origami, since I live in Japan...but alas, I didn''t. I have however tried to duplicate the shot with little success. I need to work on my lighting. You have it down pat!! Love it!!', '2008-01-20 12:57:06.000000', NULL, 0),
(4436668, 557414, 14986, '<td valign="top">I agree with most comments below.  It appears out of focus and the black border is distracting and not adding to the shot.  However, I do like the idea and the shoes have "character" (you can tell I''m a Realtor)  I like the composition as well...just the technical end of the shot needs some work.  I''m not a fan of the really red tone, but that''s a matter of taste I suppose.</td>', 'I agree with most comments below.  It appears out of focus and the black border is distracting and not adding to the shot.  However, I do like the idea and the shoes have "character" (you can tell I''m a Realtor)  I like the composition as well...just the technical end of the shot needs some work.  I''m not a fan of the really red tone, but that''s a matter of taste I suppose.', '2008-01-29 13:31:28.000000', NULL, 0),
(4488743, 559314, 16912, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by JaimeVinas:</b></div><hr/><i> This was placed in the wrong challenge. </i></td></tr></table> <br/> <br/>Excuses excuses!<br/> <br/>Either way you''ve come on in leaps and bounds my good man :)</td>', 'Originally posted by JaimeVinas: This was placed in the wrong challenge.   Excuses excuses! Either way you''ve come on in leaps and bounds my good man :)', '2008-02-15 12:41:47.000000', NULL, 0),
(4508591, 559548, 36102, '<td valign="top">I just came across this picture and I had to tell you I think it''s wonderful.  What an amazing idea and beautiful lighting.</td>', 'I just came across this picture and I had to tell you I think it''s wonderful.  What an amazing idea and beautiful lighting.', '2008-02-22 21:42:41.000000', NULL, 0),
(4548758, 559784, 90495, '<td valign="top">Beautiful lines, curves and colours. Great capture using a common object.</td>', 'Beautiful lines, curves and colours. Great capture using a common object.', '2008-03-08 17:19:32.000000', NULL, 0),
(4698021, 558760, 69008, '<td valign="top">I see that you got hammered by the voters for this not being a still life. <br/> The main problems that I see right off are the horizon out of level, and the blowout in the sky, upper left. <br/>This scene may make a much better image early or late in the day, at dawn or dusk, which would help with the sky and general strong contrast.  Not bad for a first entry though. I have been here a good while, and still enter a clunker that does not break 5 once in a while.</td>', 'I see that you got hammered by the voters for this not being a still life.  The main problems that I see right off are the horizon out of level, and the blowout in the sky, upper left. This scene may make a much better image early or late in the day, at dawn or dusk, which would help with the sky and general strong contrast.  Not bad for a first entry though. I have been here a good while, and still enter a clunker that does not break 5 once in a while.', '2008-05-12 21:00:09.000000', NULL, 0),
(4783818, 560458, 48228, '<td valign="top">This is a very strong b;ack and white image..... Quite dramatic, and the sharp focus, really help to make this one stand out.....</td>', 'This is a very strong b;ack and white image..... Quite dramatic, and the sharp focus, really help to make this one stand out.....', '2008-06-24 21:39:11.000000', NULL, 0),
(4820624, 558310, 48228, '<td valign="top"><b>SIMPLE IDEA</b>, but also a wonderful idea, done extremely well. I love the patterns of the shadows very much, and the golden rose completes this image and shows us sheer beauty at its best.....<br/> <br/>Now a favorite..... and also a ''favorite photographer'' as I thought I already had you as a ''favorite'' but noticed tonight that I don''t, but I do now.....<br/><br/><i>Message edited by author 2008-07-12 09:20:34.</i></td>', 'SIMPLE IDEA, but also a wonderful idea, done extremely well. I love the patterns of the shadows very much, and the golden rose completes this image and shows us sheer beauty at its best..... Now a favorite..... and also a ''favorite photographer'' as I thought I already had you as a ''favorite'' but noticed tonight that I don''t, but I do now.....', '2008-07-12 10:05:22.000000', '2008-07-12 10:20:34.000000', 0),
(4822436, 560288, 64629, '<td valign="top">nice work! Glad you described the set up. I don''t think alot of people realize how much time goes into a shot like this.Very interesting effects with the color.The middle glass would stand alone,the stem colors are great,I love the colors in the glass above the water,3 colors in the middle 2 on either side. Just getting the water level in each as close as you did,had to be a little tough.Anyway,great shot,you do great work.</td>', 'nice work! Glad you described the set up. I don''t think alot of people realize how much time goes into a shot like this.Very interesting effects with the color.The middle glass would stand alone,the stem colors are great,I love the colors in the glass above the water,3 colors in the middle 2 on either side. Just getting the water level in each as close as you did,had to be a little tough.Anyway,great shot,you do great work.', '2008-07-13 19:28:44.000000', NULL, 0),
(4832828, 559784, 76335, '<td valign="top">An excellent study in geometry, light and color. Beautifully processed.</td>', 'An excellent study in geometry, light and color. Beautifully processed.', '2008-07-18 18:15:35.000000', NULL, 0),
(4841224, 559515, 95697, '<td valign="top">That is absolutely gorgeous.</td>', 'That is absolutely gorgeous.', '2008-07-23 15:49:40.000000', NULL, 0),
